<?php use App\Core\Db; if($_SERVER['REQUEST_METHOD']!=='POST') exit; csrf_validate(); $pdo=Db::pdo(); $u=\App\Core\Auth::user(); $id=(int)$_POST['id']; $action=$_POST['action']; $st=$pdo->prepare("SELECT * FROM cpms_approval_lines WHERE document_id=:d AND approver_id=:u AND line_status='PENDING' LIMIT 1");$st->execute(array(':d'=>$id,':u'=>$u['id']));$l=$st->fetch(); if(!$l) exit; if($action==='reject'&&trim((string)$_POST['reject_reason'])===''){flash_set('danger','반려사유 필수');header('Location: ?r=approval_detail&id='.$id);exit;} if($action==='approve'){$sig=explode('@',$u['email']);$pdo->prepare("UPDATE cpms_approval_lines SET line_status='APPROVED',acted_at=NOW(),sign_path=:s WHERE id=:id")->execute(array(':s'=>'storage/signatures/'.$sig[0].'.png',':id'=>$l['id']));$next=(int)$l['line_order']+1;$pdo->prepare("UPDATE cpms_approval_lines SET line_status='PENDING' WHERE document_id=:d AND line_order=:o AND line_status='WAITING'")->execute(array(':d'=>$id,':o'=>$next));$pdo->prepare("UPDATE cpms_approval_documents SET doc_status=:s,current_step_order=:o,updated_at=NOW() WHERE id=:id")->execute(array(':s'=>($next>4?'APPROVED':'PENDING'),':o'=>$next,':id'=>$id));} else {$pdo->prepare("UPDATE cpms_approval_lines SET line_status='REJECTED',acted_at=NOW(),reject_reason=:r WHERE id=:id")->execute(array(':r'=>$_POST['reject_reason'],':id'=>$l['id']));$pdo->prepare("UPDATE cpms_approval_documents SET doc_status='REJECTED',reject_reason=:r,rejected_step=:s,updated_at=NOW() WHERE id=:id")->execute(array(':r'=>$_POST['reject_reason'],':s'=>$l['role_type'],':id'=>$id));} header('Location: ?r=approval_detail&id='.$id);